<script setup>
import { computed, onMounted, ref } from 'vue'
import { BadgeCheck, BookOpenCheck, CircleAlert, CloudOff, DatabaseZap, FileUp, GraduationCap, RefreshCw, Send, ShieldCheck } from '@lucide/vue'
import { bootstrapLocalLmsDemo, createLocalLmsConnection, exportLocalLmsCatalog, getLocalLmsWorkspace, importLocalLmsGrade, syncLocalLmsAssignment } from '../api/localLms'

const workspace = ref({ organizations: [], selected: null, truthfulness: null })
const loading = ref(true), action = ref(''), error = ref(''), notice = ref('')
const selected = computed(() => workspace.value.selected)
const connection = computed(() => selected.value?.connections?.[0] || null)
const assignment = computed(() => selected.value?.assignments?.[0] || null)
const course = computed(() => selected.value?.courses?.[0] || null)
const cohort = computed(() => selected.value?.cohorts?.[0] || null)
const authority = computed(() => assignment.value?.authority_counts || {})
function detailText(value) { return typeof value === 'string' ? value : value?.message || value?.code || '操作失败' }
async function load() { loading.value = true; error.value = ''; try { workspace.value = await getLocalLmsWorkspace() } catch (e) { error.value = detailText(e.detail || e.message) } finally { loading.value = false } }
async function run(key, command, message) { action.value = key; error.value = ''; notice.value = ''; try { await command(); notice.value = message; await load() } catch (e) { error.value = detailText(e.detail || e.message) } finally { action.value = '' } }
async function bootstrap() { await run('bootstrap', bootstrapLocalLmsDemo, '冻结合成培训数据和本地 LMS 连接已就绪') }
async function connect() { await run('connect', () => createLocalLmsConnection({ organization_id: selected.value.organization.id }), '本地 LMS 连接已建立') }
async function exportItem(sourceType, sourceId) { await run(`export:${sourceType}`, () => exportLocalLmsCatalog({ organization_id: selected.value.organization.id, connection_id: connection.value.id, source_type: sourceType, source_object_id: sourceId }), `${sourceType === 'course' ? '课程' : '批次'}快照已导出`) }
async function syncAssignment() { await run('assignment', () => syncLocalLmsAssignment({ organization_id: selected.value.organization.id, connection_id: connection.value.id, training_assignment_id: assignment.value.id }), '培训分配已幂等同步') }
async function importGrade() { await run('grade', () => importLocalLmsGrade({ organization_id: selected.value.organization.id, connection_id: connection.value.id, external_record_key: 'competition-lms-grade-001', training_assignment_id: assignment.value.id, course_id: course.value.id, completion_status: 'completed', score: 0.95, occurred_at: '2026-08-05T08:00:00' }), '0.95 外部成绩已保存为候选证据，内部事实未改写') }
function shortHash(value) { return value ? `${value.slice(0, 14)}...` : '—' }
onMounted(load)
</script>

<template>
  <main class="lms-page">
    <header class="page-header"><div><p class="eyebrow"><DatabaseZap :size="14" /> FC4 local integration</p><h1>LMS 课程与成绩同步</h1><p>在本地适配器中交换课程、培训批次、分配和完成摘要，并隔离外部成绩与内部事实源。</p></div><button class="icon-button" aria-label="刷新 LMS 工作台" title="刷新" @click="load"><RefreshCw :size="17" /></button></header>
    <div v-if="error" class="message error"><CircleAlert :size="16" />{{ error }}</div><div v-if="notice" class="message success"><BadgeCheck :size="16" />{{ notice }}</div><div v-if="loading" class="message loading"><RefreshCw :size="16" class="spin" />正在恢复 LMS 交换状态</div>
    <section v-if="!loading && workspace.truthfulness" class="boundary"><CloudOff :size="18" /><div><strong>{{ workspace.truthfulness.data_label }}</strong><span>{{ workspace.truthfulness.disclaimer }}</span></div></section>
    <section v-if="!loading && !selected" class="empty"><GraduationCap :size="38" /><h2>尚无可管理的培训组织</h2><p>初始化冻结合成课程、批次、学员和本地 LMS 连接。</p><button class="primary" :disabled="action === 'bootstrap'" @click="bootstrap">初始化演示闭环</button></section>
    <template v-else-if="!loading">
      <section class="facts"><div><span>组织</span><strong>{{ selected.organization.name }}</strong></div><div><span>真实 LMS</span><strong>未连接</strong></div><div><span>外部成绩地位</span><strong>仅候选证据</strong></div><div><span>内部事实覆盖</span><strong>禁止</strong></div></section>
      <section v-if="!connection" class="setup"><DatabaseZap :size="30" /><div><h2>建立本地 LMS 适配器</h2><p>适配器在本机运行，不联网、不发送真实数据，也不宣称互操作认证。</p></div><button class="primary" :disabled="action === 'connect'" @click="connect">建立连接</button></section>
      <template v-else>
        <section class="connection"><div><span>连接</span><strong>{{ connection.display_name }}</strong></div><div><span>适配器</span><strong>{{ connection.adapter_version }}</strong></div><div><span>状态</span><strong>{{ connection.status === 'active' ? '本地可用' : '已停用' }}</strong></div></section>
        <section class="flow">
          <article><div class="step"><span>01</span><FileUp :size="18" /></div><h2>导出课程</h2><p>{{ course ? `${course.title} · ${course.version}` : '等待培训课程' }}</p><button class="secondary" :disabled="!course || Boolean(action)" @click="exportItem('course', course.id)">导出冻结快照</button></article>
          <article><div class="step"><span>02</span><BookOpenCheck :size="18" /></div><h2>导出培训批次</h2><p>{{ cohort ? `${cohort.course_versions.length} 个课程版本 · ${cohort.status}` : '等待培训批次' }}</p><button class="secondary" :disabled="!cohort || Boolean(action)" @click="exportItem('cohort', cohort.id)">导出批次摘要</button></article>
          <article><div class="step"><span>03</span><Send :size="18" /></div><h2>同步学习分配</h2><p>{{ assignment ? `${assignment.learner_public_id} · ${assignment.status}` : '等待培训分配' }}</p><button class="secondary" :disabled="!assignment || Boolean(action)" @click="syncAssignment">同步分配</button></article>
          <article><div class="step"><span>04</span><ShieldCheck :size="18" /></div><h2>导入完成与成绩</h2><p>冻结示例：完成 · 0.95；只进入候选证据区。</p><button class="primary" :disabled="!assignment || !course || Boolean(action)" @click="importGrade">导入候选成绩</button></article>
        </section>
        <section class="authority"><div class="heading"><div><h2>内部权威事实隔离</h2><p>外部成绩导入前后，这些 canonical 对象数量保持不变。</p></div><span>自动保护</span></div><div class="authority-grid"><div><span>正式测评</span><strong>{{ authority.assessment_attempts ?? 0 }}</strong></div><div><span>成绩报告</span><strong>{{ authority.assessment_reports ?? 0 }}</strong></div><div><span>能力状态</span><strong>{{ authority.ability_states ?? 0 }}</strong></div><div><span>技能证据</span><strong>{{ authority.skill_evidence ?? 0 }}</strong></div><div><span>认证</span><strong>{{ authority.certifications ?? 0 }}</strong></div></div></section>
        <section class="records"><div class="heading"><div><h2>候选成绩摘要</h2><p>记录不可变；重复键同载荷幂等，异载荷冲突并拒绝覆盖。</p></div><span>{{ selected.grade_summaries.length }} 条</span></div><div v-if="!selected.grade_summaries.length" class="inline-empty">导入外部完成摘要后显示。</div><div v-else class="table"><div class="thead"><span>外部记录</span><span>完成 / 成绩</span><span>证据状态</span><span>载荷哈希</span></div><div v-for="item in selected.grade_summaries" :key="item.id" class="trow"><div><strong>{{ item.external_record_key }}</strong><small>{{ item.learner_public_id }}</small></div><div><strong>{{ item.completion_status }}</strong><small>{{ item.score ?? '无分数' }}</small></div><span class="candidate">候选 · 非权威</span><code>{{ shortHash(item.payload_hash) }}</code></div></div></section>
        <section class="history"><div class="heading"><div><h2>交换与审计</h2><p>课程/批次导出、分配同步、成绩导入和冲突均留下不可变事件。</p></div><span>{{ selected.events.length }} 个事件</span></div><div v-if="!selected.events.length" class="inline-empty">尚无交换事件。</div><div v-for="event in selected.events" :key="event.id" class="event"><span>{{ event.action }}</span><strong>{{ event.outcome }}</strong><code>{{ event.object_id }}</code><small>{{ shortHash(event.evidence_hash) }}</small></div></section>
      </template>
    </template>
  </main>
</template>

<style scoped>
.lms-page{max-width:1320px;margin:0 auto;padding:4px 2px 42px;color:#20272a}.page-header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.page-header h1{font-size:24px;font-weight:750;margin:6px 0}.page-header>div>p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#1f6370;font-size:11px;font-weight:700;text-transform:uppercase}.icon-button{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.message{display:flex;align-items:center;gap:8px;padding:11px 14px;margin-top:12px;font-size:11px}.message.error{background:#fff1ef;color:#963f35}.message.success{background:#eef8f1;color:#276046}.message.loading{background:#f4f7f8;color:#56646a}.boundary{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#fff8e6;border-bottom:1px solid #e4d7ad;color:#65511f}.boundary div{display:flex;flex-wrap:wrap;gap:5px 14px}.boundary strong{font-size:11px}.boundary span{font-size:10px;color:#78693f}.facts{display:grid;grid-template-columns:repeat(4,1fr);background:#f6f9fa;border-bottom:1px solid #dce2e5}.facts div,.connection div{padding:14px 18px;border-right:1px solid #e0e6e8}.facts span,.connection span{display:block;font-size:9px;color:#77858a}.facts strong,.connection strong{font-size:12px}.setup{min-height:290px;display:flex;justify-content:center;align-items:center;gap:18px}.setup h2,.empty h2{font-size:16px}.setup p,.empty p{font-size:10px;color:#758187;margin-top:4px}.connection{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid #dce2e5}.flow{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid #dce2e5}.flow article{min-height:210px;padding:22px 18px;border-right:1px solid #dce2e5;display:flex;flex-direction:column;align-items:flex-start}.flow article:last-child{border-right:0}.step{width:100%;display:flex;justify-content:space-between;align-items:center;color:#2e6872}.step span{font:700 10px ui-monospace,monospace;color:#839096}.flow h2{font-size:14px;margin-top:22px}.flow p{font-size:10px;color:#748087;line-height:1.55;min-height:46px;margin:7px 0 14px}.authority,.records,.history{padding:24px 0;border-bottom:1px solid #dce2e5}.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:15px}.heading h2{font-size:15px}.heading p{font-size:10px;color:#748087;margin-top:4px}.heading>span{font-size:9px;padding:5px 8px;border:1px solid #c8d8dc;border-radius:5px;color:#47717a}.authority-grid{display:grid;grid-template-columns:repeat(5,1fr);background:#dce4e6;gap:1px}.authority-grid div{background:#f6f9fa;padding:13px}.authority-grid span{display:block;font-size:9px;color:#758187}.authority-grid strong{font-size:17px}.table{border:1px solid #dce2e5}.thead,.trow{display:grid;grid-template-columns:1.2fr .8fr .8fr 1fr;align-items:center;gap:12px;padding:10px 14px}.thead{background:#f4f7f8;font-size:9px;color:#748087}.trow{border-top:1px solid #e3e8ea}.trow>div{display:flex;flex-direction:column}.trow strong{font-size:10px}.trow small,.trow code{font-size:8px;color:#78848a}.candidate{width:max-content;padding:4px 7px;border-radius:4px;background:#fff5db;color:#74551a;font-size:9px}.event{display:grid;grid-template-columns:.8fr .8fr 1.4fr .8fr;align-items:center;gap:14px;padding:10px 2px;border-bottom:1px solid #e3e8ea}.event span{font-size:9px;color:#66757b}.event strong{font-size:10px}.event code,.event small{font-size:8px;color:#7b878c}.primary,.secondary{height:34px;display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:6px;padding:0 12px;font-size:10px;font-weight:650;cursor:pointer}.primary{background:#245f69;color:#fff}.secondary{background:#eaf2f4;color:#285d67}.primary:disabled,.secondary:disabled{opacity:.5;cursor:not-allowed}.empty{min-height:380px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}.inline-empty{padding:30px;text-align:center;border:1px dashed #d1dadd;color:#78858a;font-size:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:800px){.page-header>div>p:last-child{font-size:11px}.facts{grid-template-columns:1fr 1fr}.connection{grid-template-columns:1fr}.connection div{border-bottom:1px solid #e0e6e8}.flow{grid-template-columns:1fr}.flow article{min-height:0;border-right:0;border-bottom:1px solid #dce2e5}.flow p{min-height:0}.flow button{width:100%}.authority-grid{grid-template-columns:1fr 1fr}.authority-grid div:last-child{grid-column:1/-1}.heading{align-items:flex-start;flex-direction:column}.thead{display:none}.trow,.event{grid-template-columns:1fr}.candidate{max-width:100%}}
</style>
